package com.vandorlabs.neoforge.gear;
import java.util.*;import com.vandorlabs.neoforge.navigation.*;import net.minecraft.core.*;import net.minecraft.core.component.DataComponents;import net.minecraft.nbt.CompoundTag;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.item.*;import net.minecraft.world.item.component.CustomData;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.phys.*;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.server.ServerStartedEvent;import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Real journal ownership of a cross-chunk joined Table, including exact physical module and chip. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeNavigationArmChecks {
 private static final BlockPos ROOT=new BlockPos(31,100,31),SOURCE=ROOT.above(2);private static ServerLevel world;private static Actor actor;private static int stage,ticks,checks,fractional,endpointWait;private static boolean running,leaseChecked;private static ItemStack expectedModule,expectedChip;
 private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer{Actor(ServerLevel w){super(w,new com.mojang.authlib.GameProfile(new UUID(0,211037),"NavigationArmRuntime"));}}
 private static String phase(){return System.getProperty("vandorlabs.navigationArmPhase","");}private static boolean enabled(){return Boolean.getBoolean("vandorlabs.navigationArmChecks");}private static void need(boolean valid,String why){checks++;if(!valid)throw new AssertionError("Navigation arm stage="+stage+" tick="+ticks+": "+why);}private static NativeGearEntity root(){return NativeGearFormation.at(world,ROOT);}
 private static List<net.minecraft.world.entity.item.ItemEntity> drops(){return world.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(ROOT).inflate(12));}
 private static ItemStack module(){var s=new ItemStack(NativeNavigationItems.MODULE);need(NativeNavigationModuleData.record(s,world,List.of(new NativeNavigationModuleData.Area(321,-654,1000))),"bound recorded geography");return s;}
 private static void inventory(List<NativeGearSnapshot.Cell> cells){int modules=0,chips=0,tables=0;for(var cell:cells)if(NativeGearSnapshot.stage(world,cell,false) instanceof NativeNavigationTableEntity t){need(!t.inert(),"captured table codec stays healthy");tables++;if(!t.storedModule().isEmpty()){modules++;need(ItemStack.matches(t.storedModule(),expectedModule),"sole captured module preserves full NBT");}if(!t.storedChip().isEmpty()){chips++;need(ItemStack.matches(t.storedChip(),expectedChip),"sole captured pin preserves full NBT");}}need(tables==2&&modules==1&&chips==1,"one physical module and one pin across two captured tables");need(drops().isEmpty(),"journal source publication never ejects copied inventory");}
 private static void nativeInventory(BlockPos source){int modules=0,chips=0;for(var p:new BlockPos[]{source,source.east()}){need(world.getBlockEntity(p) instanceof NativeNavigationTableEntity,"native endpoint restored both tables "+p);var t=(NativeNavigationTableEntity)world.getBlockEntity(p);need(!t.inert(),"native endpoint table healthy");if(!t.storedModule().isEmpty()){modules++;need(ItemStack.matches(t.storedModule(),expectedModule),"native module exact saved areas");}if(!t.storedChip().isEmpty()){chips++;need(ItemStack.matches(t.storedChip(),expectedChip),"native pin exact saved coordinates");}}need(modules==1&&chips==1&&drops().isEmpty(),"one native owner for module/pin without loose copies");}

 private static void nativeEndpoint(NativeGearEntity arm){int modules=0,chips=0,tables=0;for(var cell:arm.payload().cells())if(cell.state.getBlock() instanceof NativeNavigationTableBlock){tables++;need(world.getBlockEntity(cell.pos) instanceof NativeNavigationTableEntity,"native endpoint table "+cell.pos);var t=(NativeNavigationTableEntity)world.getBlockEntity(cell.pos);if(!t.storedModule().isEmpty()){modules++;need(ItemStack.matches(t.storedModule(),expectedModule),"native endpoint exact module");}if(!t.storedChip().isEmpty()){chips++;need(ItemStack.matches(t.storedChip(),expectedChip),"native endpoint exact pin");}}need(tables==2&&modules==1&&chips==1&&drops().isEmpty(),"dynamic native endpoint exactly one module/pin and no drops");}
 @SubscribeEvent public static void started(ServerStartedEvent e){if(!enabled())return;try{world=e.getServer().overworld();for(int x=1;x<=2;x++)for(int z=1;z<=2;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);actor.setPos(27.5,100,31.5);expectedModule=module();expectedChip=com.vandorlabs.neoforge.credentials.NativeChipTypes.variant("navigation");NativeNavigationChip.write(expectedChip,world,321,-654);if(phase().equals("read")){stage=4;running=true;return;}for(var p:BlockPos.betweenClosed(ROOT.offset(-5,-2,-5),ROOT.offset(5,9,5)))world.setBlock(p,p.getY()==99?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),3);var settings=NativeGearSettings.defaults().choices();settings.putBoolean("CarryLoad",true);settings.putBoolean("JoinArms",true);settings.putInt("LoadHeight",3);settings.putDouble("ActiveExtension",2);var tag=new CompoundTag();tag.put(NativeGearItem.SETTINGS,settings);var stack=new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.EXTENDER.id),4);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);for(int x=0;x<2;x++)for(int y=0;y<2;y++){var support=ROOT.east(x).above(y-1);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(0,.5,0),Direction.UP,support,false)).consumesAction(),"ordinary Survival joined Extender placement "+x+","+y);}need(stack.isEmpty(),"four arm items consumed once");actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);running=true;}catch(Throwable error){fail(error);}}
 @SubscribeEvent public static void tick(ServerTickEvent.Post e){if(!running)return;try{need(++ticks<1600,"bounded async arm ownership root="+root()+" columns="+(root()==null?-1:root().columns().size())+" error="+(root()==null?"missing":root().error()));var arm=root();if(arm==null||arm.inert()||!arm.controller()||!arm.completeMembers())return;need(!arm.blocked(),"arm remains unobstructed "+arm.error());if(stage==0){if(arm.assembly().columnHeight()!=2||arm.columns().size()!=2)return;for(var p:new BlockPos[]{SOURCE,SOURCE.east()})world.setBlock(p,NativeNavigationTableBindings.FLAT.defaultBlockState(),3);stage=1;return;}if(stage==1){var t=(NativeNavigationTableEntity)world.getBlockEntity(SOURCE);if(!t.formed()||t.assemblyWidth()!=2)return;var bay=t.hasModuleBay()?t:(NativeNavigationTableEntity)world.getBlockEntity(SOURCE.east());need(bay.installModule(expectedModule),"module enters joined table bay once");t.setChip(expectedChip);nativeInventory(SOURCE);arm.authorize(actor);need(arm.command(false),"activate ordinary joined table payload");stage=2;return;}if(stage==2||stage==5){if(!leaseChecked&&NativeGearHolds.reserved(world,SOURCE)&&world.getBlockEntity(SOURCE) instanceof NativeNavigationTableEntity target&&world.getBlockEntity(SOURCE.east()) instanceof NativeNavigationTableEntity other){var before=target.saveWithFullMetadata(world.registryAccess());var otherBefore=other.saveWithFullMetadata(world.registryAccess());var bay=target.hasModuleBay()?target:other;need(bay.takeModule().isEmpty(),"pending durable journal refuses module extraction");target.setChip(ItemStack.EMPTY);target.setTexture(-1);target.setRxChannels(com.vandorlabs.redstone.ChannelList.of(999));need(before.equals(target.saveWithFullMetadata(world.registryAccess()))&&otherBefore.equals(other.saveWithFullMetadata(world.registryAccess())),"pending durable journal refuses chip/config mutations without altering snapshots");leaseChecked=true;}if(arm.payload()!=null&&!arm.payload().materialized()){inventory(arm.payload().cells());if(fractional==0){int moduleDrops=0,chipDrops=0;for(int index=0;index<arm.payload().size();index++){var receipt=NativeGearHarvestReceipt.prepare(arm,actor,index);for(var drop:receipt.drops()){if(drop.stack().is(NativeNavigationItems.MODULE)){moduleDrops++;need(ItemStack.matches(drop.stack(),expectedModule),"captured mining receipt retains exact full module");}if(com.vandorlabs.neoforge.navigation.NativeNavigationChip.item(drop.stack())){chipDrops++;need(ItemStack.matches(drop.stack(),expectedChip),"captured mining receipt retains pin");}}}need(moduleDrops==1&&chipDrops==1,"mining receipts drop only physical anchored inventory exactly once");}fractional++;}double target=stage==2?0:1;if(arm.progress()!=target||NativeGearJournal.busy(arm))return;if(arm.payload()==null||!arm.payload().materialized()){need(++endpointWait<120,"bounded native endpoint publication progress="+arm.progress()+" endpoint="+(arm.payload()==null?-1:arm.payload().endpoint(arm,arm.progress()).size())+" cached="+(arm.payload()==null?"none":arm.cachedEndpointFailure(arm.payload()))+" error="+arm.error());return;}endpointWait=0;nativeEndpoint(arm);if(stage==5)nativeInventory(SOURCE);if(stage==2){need(fractional>0,"real fractional captured ownership exercised");need(leaseChecked,"actual reserved asynchronous prepare mutation check executed");world.getServer().saveEverything(false,true,true);finish("save");}else finish("read");return;}if(stage==4){need(arm.progress()==0&&arm.payload()!=null&&arm.payload().materialized(),"cold active endpoint retained");nativeEndpoint(arm);arm.authorize(actor);need(arm.command(true),"cold joined table reverses to original native endpoint");stage=5;}}catch(Throwable error){fail(error);}}
 private static void finish(String p){running=false;System.out.println("[vandorlabs][navigation-arm] "+p+" PASS checks="+checks+" fractional="+fractional+" realSurvivalPlacement/joinedExtenders/crossChunkTables/moduleAndPinOnce/fullGeography/nativeHandback/coldReversal");world.getServer().halt(false);}private static void fail(Throwable error){error.printStackTrace();System.err.println("[vandorlabs][navigation-arm] FAIL "+error);running=false;if(world!=null)world.getServer().halt(false);}
 private NativeNavigationArmChecks(){}
}
